<?php
declare(strict_types=1);
namespace MiniErp\Fiscal;
use DateTimeImmutable; use InvalidArgumentException;
final readonly class FiscalTaxContext {
 public function __construct(public int $tenantId,public int $establishmentId,public string $crt,public string $originState,public string $destinationState,public string $recipientType,public string $ieIndicator,public string $countryCode,public string $ncm,public string $cest,public string $productOrigin,public string $taxBenefitCode,public string $direction,public string $model,public string $purpose,public bool $finalConsumer,public bool $icmsContributor,public string $presence,public DateTimeImmutable $operationDate,public string $quantity='1.0000',public string $unitPrice='0.00',public ?string $cfopHint=null){if($tenantId<1||$establishmentId<1)throw new InvalidArgumentException('Tenant e estabelecimento são obrigatórios.');if(!in_array($direction,['ENTRY','EXIT'],true))throw new InvalidArgumentException('Direção inválida.');if(!in_array($model,['55','65'],true))throw new InvalidArgumentException('Modelo fiscal inválido.');}
 public function values():array{return ['crt'=>$this->crt,'origin_state'=>$this->originState,'destination_state'=>$this->destinationState,'recipient_type'=>$this->recipientType,'ie_indicator'=>$this->ieIndicator,'country_code'=>$this->countryCode,'ncm'=>$this->ncm,'cest'=>$this->cest,'product_origin'=>$this->productOrigin,'tax_benefit_code'=>$this->taxBenefitCode,'direction'=>$this->direction,'model'=>$this->model,'purpose'=>$this->purpose,'final_consumer'=>$this->finalConsumer,'icms_contributor'=>$this->icmsContributor,'presence'=>$this->presence,'cfop_hint'=>$this->cfopHint];}
}
